import{_ as i,l,o as a,c as d,v as t,p as r,x as o,d as n,i as s,S as h}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"Michael–Scott 无锁队列","description":"","frontmatter":{"title":"Michael–Scott 无锁队列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/michael-scott-queue.md","filePath":"cs/michael-scott-queue.md","lastUpdated":1789023840000}'),S={name:"cs/michael-scott-queue.md"};function p(u,e,A,m,C,_){const c=l("Mermaid");return a(),d("div",null,[e[1]||(e[1]=t('<h1 id="michael–scott-无锁队列" tabindex="-1">Michael–Scott 无锁队列 <a class="header-anchor" href="#michael–scott-无锁队列" aria-label="Permalink to &quot;Michael–Scott 无锁队列&quot;">​</a></h1><div class="epigraph"><p>哨兵节点永远在；enqueue CAS 尾的 next，再帮着推进 tail；dequeue CAS 头。线性化在成功的 CAS 上。</p><footer>—— 据 Michael and Scott, Simple, Fast, and Practical Non-Blocking and Blocking Concurrent Queue Algorithms, PODC 1996；Herlihy and Shavit 整理</footer></div><p><a href="/cs/lsm-tree-ds">上一课</a> 的并发在文件层。<a href="/cs/functional-queue">函数式队列</a> 无共享写。<a href="/cs/lockfree-aba">无锁与 ABA</a> 已钉 CAS 语义。<a href="/cs/atomic-rmw">原子 RMW</a> 现成。本课不 compaction。缺口是 Michael–Scott 队列：实用无锁 FIFO。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多生产者多消费者 FIFO。加锁队列简单但有锁。MS 队列：<code>head</code>、<code>tail</code> 指向节点链表，首节点是哨兵（dummy）。入队：在 <code>tail-&gt;next</code> 上 CAS 从空到新节点，成功后再 CAS <code>tail</code> 前移；若看见别人已接上 next，则帮推进 tail 再试。出队：读 <code>head-&gt;next</code> 为真头，CAS <code>head</code> 前进，旧哨兵可回收。缺口是<strong>两步 CAS 与「帮忙」以保持无锁</strong>。</p><p><span class="marginnote">Michael and Scott, <em>PODC</em>, 1996。ABA：节点回收后复用骗 CAS，需 hazard、epoch 或带 tag 指针——下一课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>节点含 <code>next</code> 与值。空队列：<code>head==tail</code> 且 next 空。实现必须先写节点内容再 CAS 链入（发布）。失败重试是无锁允许的活锁风险，实践有界。</p>',8)),(a(),r(h,null,{default:o(()=>[s(c,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENQ%5B%22enqueue%22%5D%20--%3E%20CASN%5B%22CAS%20tail.next%3A%20null%20%E2%86%92%20node%22%5D%0A%20%20CASN%20--%3E%20CAST%5B%22CAS%20%E6%8E%A8%E8%BF%9B%20tail%22%5D%0A%20%20DEQ%5B%22dequeue%22%5D%20--%3E%20CASH%5B%22CAS%20%E6%8E%A8%E8%BF%9B%20head%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与环形数组 SPSC：单生产者可无 CAS 只屏障，更快；MS 面向 MPMC。与跳表：队列无序键，只 FIFO。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>线性化：入队成功挂 next 的 CAS；出队成功移 head 的 CAS。帮忙保证 tail 不落后太多，避免无锁失败。本课不给可复现的破坏性时序作业。</p><p>回收：出队后节点不能立刻 <code>free</code>，否则 ABA 与 UAF。下一课 hazard pointer。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整可移植 C++ 实现当唯一答案。阻塞队列（两锁）是论文另一半，点名。栈的无锁更易 ABA，与 hazard 一起下一课。</p><p>后课默认：MPMC 无锁 FIFO 用 MS 队列。回收与栈用 hazard pointer。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MS 队列：哨兵链表，CAS next 与 head/tail。</li><li>无锁靠帮忙推进 tail；注意发布序。</li><li>回收与 ABA 交给 hazard。</li><li>出处：Michael and Scott, <em>PODC</em>, 1996。</li></ul>',9))])}const q=i(S,[["render",p]]);export{x as __pageData,q as default};
